module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire s0_not, s1_not;
wire and0, and1, and2, and3;

// Generate NOT signals for select bits
not (s0_not, sel[0]);
not (s1_not, sel[1]);

// Isolate each input based on select signals
and (and0, in[0], s0_not, s1_not); // sel=00
and (and1, in[1], sel[0], s1_not); // sel=01
and (and2, in[2], s0_not, sel[1]); // sel=10
and (and3, in[3], sel[0], sel[1]); // sel=11

// Combine the isolated signals to produce the output
or (out, and0, and1, and2, and3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire not_sel0, not_sel1;
wire and0, and1, and2, and3;

// Generate NOT signals for select bits
not (not_sel0, sel[0]);
not (not_sel1, sel[1]);

// Decode select signals for each input
// Input 0 selected when sel == 00
and (and0, in[0], not_sel1, not_sel0);

// Input 1 selected when sel == 01
and (and1, in[1], not_sel1, sel[0]);

// Input 2 selected when sel == 10
and (and2, in[2], sel[1], not_sel0);

// Input 3 selected when sel == 11
and (and3, in[3], sel[1], sel[0]);

// OR all the selected inputs to produce the output
or (out, and0, and1, and2, and3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire s0, s1;
wire and0, and1, and2, and3;

// Invert select signals
not (s0, sel[0]);
not (s1, sel[1]);

// Generate select conditions for each input
// Input 0 selected when sel == 00
and (and0, in[0], s1, s0);

// Input 1 selected when sel == 01
and (and1, in[1], s1, sel[0]);

// Input 2 selected when sel == 10
and (and2, in[2], sel[1], s0);

// Input 3 selected when sel == 11
and (and3, in[3], sel[1], sel[0]);

// Combine the selected inputs
or (out, and0, and1, and2, and3);

endmodule

