module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire s0_not, s1_not;
wire and0, and1, and2, and3;

// Generate NOT signals for select bits
not U1(s0_not, sel[0]);
not U2(s1_not, sel[1]);

// Decode select signals for each input
// Input 0 selected when sel == 00
and U3(and0, in[0], s0_not, s1_not);

// Input 1 selected when sel == 01
and U4(and1, in[1], sel[0], s1_not);

// Input 2 selected when sel == 10
and U5(and2, in[2], s0_not, sel[1]);

// Input 3 selected when sel == 11
and U6(and3, in[3], sel[0], sel[1]);

// OR all the decoded signals to produce the output
or U7(out, and0, and1, and2, and3);

endmodule

