module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

reg [1:0] current_state, next_state;

// State encoding
localparam IDLE = 2'b00;
localparam MOVING_UP = 2'b01;
localparam MOVING_DOWN = 2'b10;

// Sequential logic for state transition
always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end

// Combinational logic for next state
always @(*) begin
    case (current_state)
        IDLE: begin
            if (up_request && down_request) begin
                // Prioritize upward movement
                next_state = MOVING_UP;
            end else if (up_request) begin
                next_state = MOVING_UP;
            end else if (down_request) begin
                next_state = MOVING_DOWN;
            end else begin
                next_state = IDLE;
            end
        end
        MOVING_UP: begin
            // Transition back to IDLE when request ends
            if (~up_request) begin
                next_state = IDLE;
            end else begin
                next_state = MOVING_UP;
            end
        end
        MOVING_DOWN: begin
            // Transition back to IDLE when request ends
            if (~down_request) begin
                next_state = IDLE;
            end else begin
                next_state = MOVING_DOWN;
            end
        end
        default: next_state = IDLE;
    endcase
end

// Output current state
assign state = current_state;

endmodule

