module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter COLLECTING_COINS = 2'b01;
    parameter DISPENSING_ITEM = 2'b10;

    reg [1:0] current_state, next_state;
    reg [3:0] coin_total; // assuming max total is within 4 bits for simplicity

    // Define the required amount for the item
    parameter REQUIRED_AMOUNT = 4'd5;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            coin_total <= 4'd0;
        end else begin
            current_state <= next_state;
            // Update coin_total only in COLLECTING_COINS state
            if (current_state == IDLE && coin_inserted) begin
                coin_total <= coin_total + 1;
            end else if (current_state == COLLECTING_COINS && coin_inserted) begin
                coin_total <= coin_total + 1;
            end else if (current_state == DISPENSING_ITEM) begin
                coin_total <= 4'd0; // reset after dispensing
            end
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (coin_inserted)
                    next_state = COLLECTING_COINS;
                else
                    next_state = IDLE;
            end
            COLLECTING_COINS: begin
                if (item_selected && (coin_total >= REQUIRED_AMOUNT))
                    next_state = DISPENSING_ITEM;
                else
                    next_state = COLLECTING_COINS;
            end
            DISPENSING_ITEM: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;

endmodule

