module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    // Stage 1: Compute lower 8 bits sum and carry-out
    reg [7:0] sum_lower;
    reg carry_out_stage1;

    // Pipeline registers after stage 1
    reg [7:0] a_lower_reg, b_lower_reg;
    reg carry_in_reg;

    // Stage 2: Compute upper 8 bits sum with carry-in
    reg [7:0] sum_upper;
    reg carry_out_stage2;

    // Pipeline registers after stage 2
    reg [7:0] a_upper_reg, b_upper_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all registers
            sum_lower <= 8'b0;
            carry_out_stage1 <= 1'b0;
            a_lower_reg <= 8'b0;
            b_lower_reg <= 8'b0;
            carry_in_reg <= 1'b0;
            sum_upper <= 8'b0;
            carry_out_stage2 <= 1'b0;
            a_upper_reg <= 8'b0;
            b_upper_reg <= 8'b0;
            out <= 16'b0;
        end else begin
            // Stage 1: compute sum of lower 8 bits
            sum_lower <= a[7:0] + b[7:0];
            carry_out_stage1 <= (a[7:0] + b[7:0]) < a[7:0] ? 1'b1 : 1'b0; // Detect carry
            // Register inputs for stage 2
            a_lower_reg <= a[7:0];
            b_lower_reg <= b[7:0];
            carry_in_reg <= carry_out_stage1;

            // Stage 2: compute sum of upper 8 bits with carry-in
            {carry_out_stage2, sum_upper} <= {1'b0, a[15:8]} + {1'b0, b[15:8]} + carry_in_reg;

            // Register upper inputs for next cycle if needed
            a_upper_reg <= a[15:8];
            b_upper_reg <= b[15:8];

            // Combine results into output
            out <= {sum_upper, sum_lower};
        end
    end

endmodule

module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

reg [7:0] sum_lower, sum_upper;
reg carry_out_lower, carry_in_upper;
reg [7:0] a_upper, b_upper;
reg [7:0] a_lower, b_lower;

// Stage 1: Compute lower 8 bits sum and carry-out
wire [7:0] a_lower_wire = a[7:0];
wire [7:0] b_lower_wire = b[7:0];
wire [8:0] sum_lower_wire = a_lower_wire + b_lower_wire;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum_lower <= 8'b0;
        carry_out_lower <= 1'b0;
    end else begin
        sum_lower <= sum_lower_wire[7:0];
        carry_out_lower <= sum_lower_wire[8];
    end
end

// Stage 2: Compute upper 8 bits sum with carry-in from lower stage
wire [7:0] a_upper_wire = a[15:8];
wire [7:0] b_upper_wire = b[15:8];
wire [8:0] sum_upper_wire = a_upper_wire + b_upper_wire + carry_in_upper;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum_upper <= 8'b0;
        carry_in_upper <= 1'b0;
    end else begin
        sum_upper <= sum_upper_wire[7:0];
        carry_in_upper <= carry_out_lower;
    end
end

// Register the final output
always @(posedge clk or posedge rst) begin
    if (rst) begin
        out <= 16'b0;
    end else begin
        out <= {sum_upper, sum_lower};
    end
end

// Optional: To output the final carry-out from the second stage, 
