module pipelined_accumulator (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] out
);

reg [7:0] stage1_reg;        // Register to hold current input at stage 1
reg [15:0] stage2_reg;       // Register to hold accumulated sum at stage 2

// Stage 1: Add current input to previous partial sum
always @(posedge clk or posedge rst) begin
    if (rst) begin
        stage1_reg <= 8'b0;
    end else begin
        stage1_reg <= x;
    end
end

// Stage 2: Accumulate partial sum from stage 1
always @(posedge clk or posedge rst) begin
    if (rst) begin
        stage2_reg <= 16'b0;
    end else begin
        stage2_reg <= stage2_reg + stage1_reg;
    end
end

// Output assignment after 4 cycles
// To accumulate total sum over 4 inputs, we need an additional register
// to hold the sum after 4 cycles. Since the pipeline is 2-stage,
// we can chain the accumulation or use a counter. But as per the problem,
// the final output after 4 cycles is the total sum.
// For simplicity, we can assign the final accumulated value after 4 cycles
// by capturing stage2_reg at the appropriate cycle.

reg [15:0] sum_reg;
reg [1:0] cycle_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sum_reg <= 16'b0;
        cycle_count <= 2'b0;
        out <= 16'b0;
    end else begin
        if (cycle_count < 2'b11) begin
            cycle_count <= cycle_count + 1;
        end
        // After 4 cycles, output the accumulated sum
        if (cycle_count == 2'b11) begin
            out <= stage2_reg;
        end
    end
end

endmodule

