    input [15:0] future_amount,
    input [7:0] rate,
    input [7:0] n,
    output reg [15:0] present_value
);

// Fixed-point scaling factor (e.g., 8 bits for fractional part)
parameter SCALE = 8;

// Internal signals
reg [15:0] base;            // (1 + rate/100) scaled
reg [15:0] power;           // (1 + rate/100)^n scaled
reg [15:0] denominator;     // Denominator for division
reg [31:0] numerator;       // Numerator for division
reg [15:0] temp_power;
reg [7:0] count;

// Step 1: Compute (1 + rate/100) scaled
// rate is in percentage, so rate/100 is rate/100
// To represent (1 + rate/100), scaled by 2^SCALE
// (1 + rate/100) = 1 + rate/100
// scaled_value = (1 + rate/100) * 2^SCALE
// Since rate is in [0,255], rate/100 in fixed point is (rate * 2^SCALE) / 100
// But to keep it simple, we do:
always @(*) begin
    // Compute rate/100 in fixed point
    // rate/100 scaled by 2^SCALE
    // To avoid fractional division, multiply first then divide
    // scaled_rate = (rate * 2^SCALE) / 100
    // Then add 1 in scaled form: 1 * 2^SCALE
    base = ( (rate * (1 << SCALE)) ) / 100 + (1 << SCALE);
end

// Step 2: Compute (1 + rate/100)^n using iterative multiplication
// Initialize power to base
// Loop n times: power = power * base / 2^SCALE
// Since fixed-point multiplication: (a * b) >> SCALE
always @(*) begin
    power = (1 << SCALE); // start with 1 in fixed point
    for (count = 0; count < n; count = count + 1) begin
        // Multiply power * base, then shift right by SCALE
        temp_power = (power * base) >> SCALE;
        power = temp_power;
    end
end

// Step 3: Compute denominator = (1 + rate/100)^n scaled
// Already computed in 'power'

// Step 4: Compute present_value = future_amount / denominator
// To perform division, convert numerator to fixed point
// numerator = future_amount * 2^SCALE
// Then divide by denominator
always @(*) begin
    numerator = future_amount * (1 << SCALE);
    // To avoid division by zero
    if (denominator != 0) begin
        // Fixed-point division
        // result = numerator / denominator
        // Since numerator is scaled, result is in fixed point
        // Convert back to integer by shifting right by SCALE
        present_value = numerator / denominator;
    end else begin
        present_value = 16'd0;
    end
end

