reg [15:0] power;           // (1 + rate/100)^n scaled
reg [15:0] denominator;     // Denominator for division
reg [31:0] numerator;       // Numerator for division (extended for precision)
reg [15:0] temp;            // Temporary variable for multiplication
reg [7:0] count;            // Loop counter

// State machine states
reg [1:0] state;
localparam IDLE = 2'd0,
           CALC_POWER = 2'd1,
           DIVIDE = 2'd2,
           DONE = 2'd3;

// Initialize
initial begin
    present_value = 0;
    state = IDLE;
end

// Helper task: fixed-point multiplication
task fixed_mul;
    input [15:0] a;
    input [15:0] b;
    output [15:0] result;
    reg [31:0] mult;
begin
    mult = a * b; // 16x16 multiplication -> 32 bits
    // Adjust back to fixed-point by shifting right by SCALE bits
    result = mult[31:SCALE];
end
endtask

// Helper task: fixed-point division (numerator / denominator)
task fixed_div;
    input [31:0] num; // numerator extended
    input [15:0] den; // denominator
    output [15:0] result;
    reg [31:0] quotient;
    reg [31:0] rem;
    integer i;
begin
    // Initialize
    quotient = 0;
    rem = num;

    // Perform division via restoring algorithm
    for (i = 0; i < 16; i = i + 1) begin
        rem = rem << 1;
        quotient = quotient << 1;
        if (rem >= (den << (16 - 1))) begin
            rem = rem - (den << (16 - 1));
            quotient = quotient + 1;
        end
    end
    result = quotient[15:0];
end
endtask

always @(*) begin
    case (state)
        IDLE: begin
            // Compute base = 1 + rate/100 scaled by SCALE
            // rate/100 in fixed-point: (rate * 2^SCALE) / 100
            // 1 in fixed-point: 1 << SCALE
            base = ( (rate * (1 << SCALE)) ) / 100 + (1 << SCALE);
            power = (1 << SCALE); // Initialize power to 1 in fixed-point
            count = 0;
            state = CALC_POWER;
        end

        CALC_POWER: begin
            if (count < n) begin
                // power = power * base
                fixed_mul(power, base, temp);
                power = temp;
                count = count + 1;
            end else begin
                // After loop, power holds (1 + rate/100)^n scaled
                // Compute denominator = power
                denominator = power;
                // Compute numerator = future_amount << SCALE for fixed-point division
                numerator = {future_amount, 16'b0}; // Extend numerator for precision
                // Perform division: future_amount / denominator
                fixed_div(numerator, denominator, present_value);
                state = DONE;
            end
        end

        DONE: begin
            // Final output ready
            // Remain in DONE state
        end

        default: state = IDLE;
    endcase
end

// State transition logic
always @(posedge clk) begin
    if (reset) begin
        present_value <= 0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                // Trigger calculation
                state <= IDLE; // Will move to CALC_POWER in combinational logic
            end
            CALC_POWER: begin
                // Handled in combinational logic
            end
            DONE: begin
                // Hold output
            end
        endcase
    end
end

