module wavelength (
    input [7:0] frequency,   // frequency in MHz
    output [7:0] wavelength  // wavelength in meters
);

wire [15:0] division_result;
wire is_zero;

// Check if frequency is zero
assign is_zero = (frequency == 8'd0);

// Perform division only if frequency is not zero
// Since c=300, we multiply numerator by 1 to perform division
// To avoid division by zero, assign zero when frequency is zero
assign division_result = is_zero ? 16'd0 : (16'd300 / frequency);

// Clip the result to 8 bits
// Since 300/1=300 (fits in 8 bits), and for larger f, the quotient decreases
// The division result is at most 8 bits, but to be safe, mask the lower 8 bits
assign wavelength = is_zero ? 8'd0 : division_result[7:0];

endmodule

